// Small helpers for showing dates and text. All dates in the store are ISO strings.

const DAY = 24 * 60 * 60 * 1000

// "Nora Alqahtani" -> "NA", "stc" -> "ST"
export function initials(name = '') {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (parts.length === 0) return '?'
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase()
  return (parts[0][0] + parts[1][0]).toUpperCase()
}

// "Jun 30, 2026"
export function formatDate(iso) {
  if (!iso) return '-'
  return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

// "September 1, 2026"
export function formatLongDate(iso) {
  if (!iso) return '-'
  return new Date(iso).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })
}

// "Jun 30, 2026, 10:42 AM"
export function formatDateTime(iso) {
  if (!iso) return '-'
  return new Date(iso).toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  })
}

// whole days from today until the date (negative if it already passed)
export function daysUntil(iso) {
  const start = new Date()
  start.setHours(0, 0, 0, 0)
  const end = new Date(iso)
  end.setHours(0, 0, 0, 0)
  return Math.round((end - start) / DAY)
}

// "2 days ago", "Yesterday", "20 minutes ago"
export function timeAgo(iso) {
  const diff = Date.now() - new Date(iso).getTime()
  const minutes = Math.floor(diff / 60000)
  if (minutes < 1) return 'Just now'
  if (minutes < 60) return `${minutes} minute${minutes === 1 ? '' : 's'} ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`
  const days = Math.floor(hours / 24)
  if (days === 1) return 'Yesterday'
  if (days < 7) return `${days} days ago`
  const weeks = Math.floor(days / 7)
  if (weeks < 5) return `${weeks} week${weeks === 1 ? '' : 's'} ago`
  return formatDate(iso)
}

// "Closes in 2 days" / "Closes today" / "Closed" / "Closes Jun 28"
export function deadlineLabel(iso) {
  const days = daysUntil(iso)
  if (days < 0) return 'Closed'
  if (days === 0) return 'Closes today'
  if (days === 1) return 'Closes tomorrow'
  if (days <= 7) return `Closes in ${days} days`
  return `Closes ${new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`
}

// weeks -> "6 months" / "8 weeks"
export function durationLabel(weeks) {
  if (!weeks) return '-'
  if (weeks % 4 === 0 && weeks >= 12) return `${weeks / 4} months`
  return `${weeks} weeks`
}

// returns an ISO date string N days from now (used by the seed data)
export function daysFromNow(days, hour = 9) {
  const d = new Date()
  d.setDate(d.getDate() + days)
  d.setHours(hour, 0, 0, 0)
  return d.toISOString()
}

// "Good morning" / "Good afternoon" / "Good evening"
export function greeting() {
  const h = new Date().getHours()
  if (h < 12) return 'Good morning'
  if (h < 18) return 'Good afternoon'
  return 'Good evening'
}
/*
  Download a table as CSV or Excel (FR-C9 shortlist export). No library needed.

    downloadTable({
      fileName: 'AI Engineer Trainee shortlist 2026-11-14',
      format: 'csv',                       // or 'excel'
      columns: [{ key: 'name', label: 'Name' }, { key: 'gpa', label: 'GPA' }],
      rows: [{ name: 'Sara', gpa: 3.7 }],
    })
*/

function escapeCsv(value) {
  const text = String(value ?? '')
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text
}

function escapeXml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

function triggerDownload(blob, fileName) {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = fileName
  document.body.appendChild(a)
  a.click()
  a.remove()
  URL.revokeObjectURL(url)
}

export function downloadTable({ fileName, format = 'csv', columns, rows }) {
  if (format === 'excel') {
    // SpreadsheetML 2003 - opens directly in Excel
    const header = columns.map((c) => `<Cell><Data ss:Type="String">${escapeXml(c.label)}</Data></Cell>`).join('')
    const body = rows
      .map(
        (row) =>
          `<Row>${columns
            .map((c) => {
              const v = row[c.key]
              const type = typeof v === 'number' ? 'Number' : 'String'
              return `<Cell><Data ss:Type="${type}">${escapeXml(Array.isArray(v) ? v.join(', ') : v)}</Data></Cell>`
            })
            .join('')}</Row>`,
      )
      .join('')
    const xml = `<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Shortlist"><Table><Row>${header}</Row>${body}</Table></Worksheet></Workbook>`
    triggerDownload(new Blob([xml], { type: 'application/vnd.ms-excel' }), `${fileName}.xls`)
    return
  }

  const lines = [
    columns.map((c) => escapeCsv(c.label)).join(','),
    ...rows.map((row) => columns.map((c) => escapeCsv(Array.isArray(row[c.key]) ? row[c.key].join('; ') : row[c.key])).join(',')),
  ]
  // BOM so Excel opens Arabic names correctly
  triggerDownload(new Blob(['﻿' + lines.join('\n')], { type: 'text/csv;charset=utf-8' }), `${fileName}.csv`)
}
// Short unique ids for new records: makeId('app') -> 'app_lq3k9x_4f2a'
export function makeId(prefix = 'id') {
  const time = Date.now().toString(36)
  const rand = Math.random().toString(36).slice(2, 6)
  return `${prefix}_${time}_${rand}`
}
import { twMerge } from 'tailwind-merge'

// Joins class names, skips empty values, and lets later Tailwind classes win
// over earlier ones that do the same thing:
// cn('px-2 inline-flex', isActive && 'bg-primary', 'hidden sm:inline-flex') -> 'px-2 bg-primary hidden sm:inline-flex'
export function cn(...classes) {
  return twMerge(classes.filter(Boolean).join(' '))
}
