    { id: 'tbl_ai_python', listingId: 'l_ai_trainee', name: 'Strong ML background', applicationIds: ['app_ai_s_reem', 'app_ai_s_faisal', 'app_ai_s_sara'], isShortlist: false, createdBy: 'company', createdAt: daysFromNow(-2) },
