  return (
    <div className="mt-8 grid gap-6 lg:grid-cols-[1fr_360px]">
      <ApplicantPool
        apps={poolApps}
        sort={sort}
        onSortChange={setSort}
        selected={selected}
        onToggle={toggle}
        onAddToTable={() => {}}
      />
    </div>
  )
}

