        open={!!deleting}
        title="Delete this table?"
        message={deleting ? `"${deleting.name}" will be deleted. The applicants stay in the applicants list.` : ''}
        confirmLabel="Delete table"
        danger
        onCancel={() => setDeleting(null)}
        onConfirm={() => {
