        {tables.map((table) => (
          <ShortlistTableCard
            key={table.id}
            table={table}
            appsById={appsById}
            readOnly={readOnly}
            {...(readOnly ? {} : tableHandlers(table))}
          />
        ))}
      </div>
    </section>
  )
}

