// Minimal Chrome DevTools Protocol driver for headless Edge (no packages needed).
import { spawn } from 'node:child_process'
import { mkdirSync, writeFileSync } from 'node:fs'

const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'
const PORT = 9333
export const BASE = 'http://localhost:5173'
export const OUT = 'C:/Users/user/AppData/Local/Temp/claude/55f7fe147959a2e6/8053ebbf-5618-42c1-bca4-7c85a90f3cba/scratchpad/shots'
mkdirSync(OUT, { recursive: true })

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

export async function launch({ width = 1440, height = 1000 } = {}) {
  const proc = spawn(EDGE, [
    '--headless=new',
    `--remote-debugging-port=${PORT}`,
    `--user-data-dir=${OUT}/../edge-profile-${Date.now()}`,
    `--window-size=${width},${height}`,
    '--no-first-run',
    '--disable-extensions',
    'about:blank',
  ])
  let targets
  for (let i = 0; i < 50; i++) {
    try {
      targets = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      if (targets.some((t) => t.type === 'page')) break
    } catch {
      // not ready yet
    }
    await sleep(200)
  }
  const page = targets.find((t) => t.type === 'page')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  await new Promise((r) => ws.addEventListener('open', r, { once: true }))

  let id = 0
  const pending = new Map()
  const errors = []
  ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data)
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id)
      pending.delete(msg.id)
      if (msg.error) reject(new Error(msg.error.message))
      else resolve(msg.result)
    }
    if (msg.method === 'Runtime.exceptionThrown') errors.push('EXCEPTION ' + (msg.params.exceptionDetails.exception?.description ?? msg.params.exceptionDetails.text))
    if (msg.method === 'Runtime.consoleAPICalled' && (msg.params.type === 'error' || msg.params.type === 'warning')) {
      errors.push(`console.${msg.params.type}: ` + msg.params.args.map((a) => a.value ?? a.description ?? '').join(' '))
    }
    if (msg.method === 'Log.entryAdded' && msg.params.entry.level === 'error') errors.push('log: ' + msg.params.entry.text + ' ' + (msg.params.entry.url ?? ''))
  })
  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const n = ++id
      pending.set(n, { resolve, reject })
      ws.send(JSON.stringify({ id: n, method, params }))
    })

  await send('Runtime.enable')
  await send('Log.enable')
  await send('Page.enable')
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: width < 600 })

  const api = {
    errors,
    send,
    sleep,
    async eval(expr) {
      const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })
      if (r.exceptionDetails) throw new Error('eval failed: ' + (r.exceptionDetails.exception?.description ?? r.exceptionDetails.text))
      return r.result.value
    },
    async goto(path, wait = 1200) {
      await send('Page.navigate', { url: BASE + path })
      await sleep(wait)
    },
    async shot(name, full = true) {
      let clip
      if (full) {
        const m = await send('Page.getLayoutMetrics')
        clip = { x: 0, y: 0, width: m.cssContentSize.width, height: Math.min(m.cssContentSize.height, 4000), scale: 1 }
      }
      const r = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: full, ...(clip ? { clip } : {}) })
      writeFileSync(`${OUT}/${name}.png`, Buffer.from(r.data, 'base64'))
    },
    // click the first element whose text matches (optionally inside a selector)
    async click(text, selector = 'button, a, [role=tab], label') {
      const ok = await api.eval(`(() => {
        const els = [...document.querySelectorAll(${JSON.stringify(selector)})].filter(e => e.offsetParent !== null || e.getClientRects().length)
        const el = els.find(e => e.textContent.trim() === ${JSON.stringify(text)}) || els.find(e => e.textContent.trim().includes(${JSON.stringify(text)}))
        if (!el) return false
        el.click(); return true
      })()`)
      if (!ok) throw new Error('click target not found: ' + text)
      await sleep(400)
    },
    async type(selector, value) {
      await api.eval(`(() => {
        const el = document.querySelector(${JSON.stringify(selector)})
        const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype
        Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, ${JSON.stringify(value)})
        el.dispatchEvent(new Event('input', { bubbles: true }))
      })()`)
      await sleep(200)
    },
    async text() {
      return api.eval('document.body.innerText')
    },
    async center(expr) {
      return api.eval(`(() => { const el = ${expr}; if (!el) return null; el.scrollIntoView({block:'center'}); const r = el.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2 } })()`)
    },
    async drag(from, to) {
      const m = (type, p, extra = {}) => send('Input.dispatchMouseEvent', { type, x: p.x, y: p.y, button: 'left', buttons: type === 'mouseReleased' ? 0 : 1, clickCount: 1, ...extra })
      await m('mouseMoved', from, { buttons: 0 })
      await m('mousePressed', from)
      for (let i = 1; i <= 12; i++) {
        await m('mouseMoved', { x: from.x + ((to.x - from.x) * i) / 12, y: from.y + ((to.y - from.y) * i) / 12 })
        await sleep(30)
      }
      await m('mouseReleased', to)
      await sleep(500)
    },
    async login(accountId) {
      await api.goto('/', 800)
      await api.eval(`localStorage.setItem('internconnect-session', ${JSON.stringify(accountId)})`)
    },
    async resetData() {
      await api.goto('/', 800)
      await api.eval(`localStorage.removeItem('internconnect-data-v1'); localStorage.removeItem('internconnect-ai-down')`)
    },
    close() {
      ws.close()
      proc.kill()
    },
  }
  return api
}

