import { launch } from './cdp.mjs'

const b = await launch({ width: 390, height: 844 })
const out = []
const overflow = () => b.eval('document.documentElement.scrollWidth - window.innerWidth')
try {
  await b.resetData()
  await b.login('c_aramco')
  for (const [name, path] of [
    ['m-workspace', '/company/postings/l_ai_trainee/applicants'],
    ['m-locked', '/company/postings/l_swe_coop/applicants'],
    ['m-shortlist', '/company/postings/l_cyber_summer/shortlist'],
  ]) {
    await b.goto(path, 1500)
    out.push(`${(await overflow()) <= 0 ? 'PASS' : 'FAIL'}  ${path} no page overflow (${await overflow()}px)`)
    await b.shot(name)
  }
  await b.eval(`localStorage.removeItem('internconnect-session')`)
  await b.login('a_admin')
  for (const p of ['requests', 'users', 'postings', 'imports', 'sources', 'statistics']) {
    await b.goto('/admin/' + p, 1500)
    out.push(`${(await overflow()) <= 0 ? 'PASS' : 'FAIL'}  /admin/${p} no page overflow (${await overflow()}px)`)
    await b.shot('m-' + p)
  }
} catch (e) {
  out.push('ERROR ' + e.message)
} finally {
  console.log(out.join('\n'))
  console.log('ERRORS:', b.errors.filter((x) => !x.includes('favicon.ico')))
  b.close()
}

