      await m('mouseMoved', from, { buttons: 0 })
      await m('mousePressed', from)
      for (let i = 1; i <= 12; i++) {
        await m('mouseMoved', { x: from.x + ((to.x - from.x) * i) / 12, y: from.y + ((to.y - from.y) * i) / 12 })
        await sleep(30)
      }
      await m('mouseReleased', to)
      await sleep(500)
    },
    // log in through the real login page with a demo-account button
    async login(accountId) {
      const label = { c_aramco: 'Company', a_admin: 'Admin' }[accountId]
      await api.goto('/login', 1200)
      await api.click(label, 'button')
      await api.click('Log in', 'button[type=submit]')
      await sleep(1200)
    },
    // fresh demo data: clear storage on a blank page of the same origin, before the app writes again
    async resetData() {
      await api.goto('/favicon.svg', 500)
      await api.eval(`localStorage.clear()`)
    },
    close() {
      ws.close()
      proc.kill()
    },
  }
  return api
}

